-- 3) Danh muc: muc tinh sai ten -> bao dam co muc ten chuan trong cung nhom roi xoa ban sai.
--    (Muc tinh co parent NULL nen UNIQUE(nhom, gia_tri, parent) KHONG chan trung - khong dung
--    UPDATE OR IGNORE nhu buoc 2 duoc, se sinh nhieu dong 'Đắk Nông'.)
INSERT INTO settings_option (nhom, gia_tri, parent)
  SELECT DISTINCT s.nhom, 'Đắk Nông', NULL FROM settings_option s
